plan,curve,info=compile_path(lib,'x+021_y-001_axis09_29',c,left_target=pose['left_joints_rad']);t0=np.array(plan['times_s']);q0=np.tile(lib.ready,(len(t0),1));q0[:,:7]=np.asarray(plan['positions_rad'])[:,:7];q0[:,14:21]=np.asarray(plan['positions_rad'])[:,7:];at=paths['align_t'];aq=paths['align_q'];bt=paths['parallel_t'];bq=paths['parallel_q'];read_at=t0[-1]+at[-1];t=np.r_[t0,t0[-1]+at[1:],read_at+bt[1:]];q=np.vstack([q0,aq[1:],bq[1:]])

def frames(times,positions):
 result=[]
 ids=sorted(set(range(0,len(times),3))|{len(times)-1,int(np.argmin(abs(times-(record['timestamp_s'] if len(times)==len(ep['times']) else read_at))))})
 for i in ids:
  fk=robot.fk(positions[i]);f=dict(t=float(times[i]))
  for side,prefix in [('left','arm_l_joint'),('right','arm_r_joint')]:f[side]=[fk[robot.joints[prefix+str(j)]['child']][:3,3].tolist() for j in range(1,8)]+[fk[robot.ee[side]][:3,3].tolist()]
  result.append(f)
 return result
