html='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>데이터셋 리딩 자세 · episode 0</title><style>body{background:#edf2f6;color:#173449;font:15px system-ui;max-width:1280px;margin:22px auto;padding:0 18px}h1{font-size:25px}p{line-height:1.7}.tag{background:#e2f2e7;padding:7px 12px;display:inline-block;border-radius:7px}.row{display:grid;grid-template-columns:1.25fr 1fr;gap:14px}canvas{width:100%;height:530px;background:white;border-radius:12px;touch-action:none}video,img{width:100%;border-radius:10px}.card{background:white;padding:14px;border-radius:12px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}button,select{padding:8px 12px;background:white;border:1px solid #b8c9d3;border-radius:6px}input{flex:1;min-width:130px}table{width:100%;border-collapse:collapse;background:white}td,th{padding:8px;border-bottom:1px solid #dce5eb;text-align:right}td:first-child,th:first-child{text-align:left}.note{color:#82642a}.stage{font-weight:bold;color:#237967}@media(max-width:950px){.row{grid-template-columns:1fr}}</style><span class="tag">데이터셋 왼팔만 적용 · 오른팔은 기존 스캔 포즈 유지</span><h1>바코드 리딩 자세 — 8.10초 / 프레임 243</h1><p>영상으로 확인한 리딩 구간(7~14초)에서 양팔 관절속도 &lt;0.1rad/s인 샘플 중 <b>왼손 X + 오른손 X가 최대</b>인 자세입니다.<br>전체 영상의 X 최대 시점은 준비·복귀였으므로 제외했습니다. 접촉3초 후4초까지 왼팔 기본자세를 유지하고,4초부터 오른팔 경유점 이동과 함께 왼팔도 스캔자세로 이동합니다. 이전 추가 yaw15°와 J6 굽힘은 중복 적용하지 않습니다.</p><div class="row"><div class="card"><canvas></canvas><div class="controls"><select id="mode"><option value="applied">새 BT 경로</option><option value="episode">원본 에피소드 관절 기록</option></select><button id="play">재생</button><button id="reading">리딩 자세</button><button id="parallel">양팔 동시 이동</button><button id="top">위에서</button><button id="front">정면</button></div><div class="controls"><input type="range" id="time" min="0" step=".01"><span id="clock"></span></div><div class="stage" id="stage"></div><p>청색: 왼팔 L-J1~L-J7 · 주황: 오른팔 R-J1~R-J7<br>J1은 어깨 쪽, J7은 손목 끝 쪽입니다. 드래그로 회전합니다.</p></div><div class="card"><video id="video" controls preload="metadata" src="source/videos/chunk-000/observation.images.ego/episode_000000.mp4"></video><p>원본 episode 0 영상. 새 경로 모드에서는 선정한8.10초 장면을 참고용으로 고정합니다.</p><img src="selected-left.jpg"><p>선정 시점의 왼손 카메라. 영상으로 리더-봉투 정렬을 확인했으며, 실제 바코드 판독 성공 신호는 이 데이터에 없습니다.</p></div></div><p class="note">스켈레톤은 현재 설치 URDF에 기록 관절각을 매핑한 FK입니다. 새 경로 재생은 실제 로봇 실행 영상이 아닙니다. 오른팔은 기존 경유점→스캔 경로를 유지합니다. 왼팔은4초부터 이동하여 경유점 통과 시점(기준6초)에 스캔자세 도착 후 유지합니다. 원본 영상의 오른팔 자세와 적용하는 오른팔 자세는 다릅니다. 봉투 부피와 양팔 상호 충돌 검사는 포함하지 않습니다.</p><p><a href="parallel-scan.gif">양팔 동시 이동 애니메이션</a></p><img src="parallel-scan.png"><div id="coordinates"></div><div id="table"></div><img src="reading-pose.png"><p>출처: <a href="https://huggingface.co/datasets/woozziam/deux_breadbag_barcodescan_gr00t_261029_unaligned">woozziam/deux_breadbag_barcodescan_gr00t_261029_unaligned</a> · episode 0만 다운로드 · <a href="reading-pose.json">적용 관절값 JSON</a> · <a href="path-validation.json">경로 검사 결과</a></p><script>
const D=__DATA__,cv=document.querySelector('canvas'),ctx=cv.getContext('2d'),sl=document.querySelector('#time'),video=document.querySelector('video');let mode='applied',t=D.read_at_s,playing=false,last=0,az=-.95,el=.42,zoom=1,W=700,H=530,drag=null;
function fs(){return D[mode]}function total(){return fs().at(-1).t}function proj(p){let x=p[0]-.28,y=p[1],z=p[2]-.95,s=Math.min(W/1.65,H/1.5)*zoom;return[W/2+(-Math.sin(az)*x+Math.cos(az)*y)*s,H/2-(-Math.cos(az)*Math.sin(el)*x-Math.sin(az)*Math.sin(el)*y+Math.cos(el)*z)*s]}
function line(ps,c,w=3){ctx.beginPath();ps.forEach((p,i)=>{let v=proj(p);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke()}
function label(p,s,c,dx=8,dy=-8){let v=proj(p);ctx.font='bold 12px system-ui';ctx.strokeStyle='white';ctx.lineWidth=4;ctx.strokeText(s,v[0]+dx,v[1]+dy);ctx.fillStyle=c;ctx.fillText(s,v[0]+dx,v[1]+dy)}
function pose(){let frames=fs(),i=0;while(i<frames.length-2&&frames[i+1].t<t)i++;let a=frames[i],b=frames[i+1],u=Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t)));return Object.fromEntries(['left','right'].map(s=>[s,a[s].map((p,j)=>p.map((v,k)=>v+(b[s][j][k]-v)*u))]))}
function draw(){sl.max=total();ctx.clearRect(0,0,W,H);for(let ps of D.polygons){ctx.beginPath();ps.forEach((p,i)=>{let v=proj(p);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.fillStyle='#7d969733';ctx.fill()}
let f=pose(),a=f.left[0],b=f.right[0];line([a,b],'#a0afbb',6);line([[0,0,.5],[0,0,(a[2]+b[2])/2]],'#a0afbb',6);for(let [s,c,prefix]of [['left','#4089bd','L'],['right','#e47e2d','R']]){line(fs().map(f=>f[s].at(-1)),c+'44',1.5);line(f[s],c,5);f[s].forEach((v,j)=>{let xy=proj(v);ctx.beginPath();ctx.arc(...xy,4,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();if(j<7)label(v,prefix+'-J'+(j+1),c,j%2?9:-32,j%2?-10:15)})}sl.value=t;document.querySelector('#clock').textContent=t.toFixed(2)+' / '+total().toFixed(2)+'s';document.querySelector('#stage').textContent=mode==='episode'?'원본 에피소드 기록 관절 FK':t<3?'접근→하강·손 닫기':t<4?'추종 상승':t<6?'오른팔→우측 경유점 + 왼팔→스캔 (동시)':t<D.scan_at_s?'왼팔 스캔 유지 · 오른팔→기존 스캔':t<D.read_at_s?'스캔 포즈 확인 (팔 이동 없음)':t<D.read_at_s+.01?'선정 리딩 자세':t<D.read_at_s+D.parallel_report.right_approach_release_s?'왼손 후퇴 + 오른손 적재':t<D.read_at_s+D.parallel_report.right_approach_release_s+D.parallel_report.stationary_open_s?'양팔 정지·손 열기':'오른손 후퇴';}
function sync(){video.pause();video.currentTime=mode==='episode'?t:D.record.timestamp_s}video.onloadedmetadata=sync;function resize(){W=cv.clientWidth;H=cv.clientHeight;let r=devicePixelRatio||1;cv.width=W*r;cv.height=H*r;ctx.setTransform(r,0,0,r,0,0);draw()}addEventListener('resize',resize);document.querySelector('#mode').onchange=e=>{mode=e.target.value;t=mode==='episode'?D.record.timestamp_s:D.read_at_s;playing=false;sync();draw()};document.querySelector('#play').onclick=()=>{if(t>=total())t=0;playing=!playing;document.querySelector('#play').textContent=playing?'일시정지':'재생'};sl.oninput=()=>{t=+sl.value;playing=false;sync();draw()};document.querySelector('#reading').onclick=()=>{t=mode==='episode'?D.record.timestamp_s:D.read_at_s;playing=false;sync();draw()};document.querySelector('#parallel').onclick=()=>{mode='applied';document.querySelector('#mode').value=mode;t=5.;playing=false;sync();draw()};document.querySelector('#top').onclick=()=>{az=-Math.PI/2;el=Math.PI/2;draw()};document.querySelector('#front').onclick=()=>{az=0;el=.1;draw()};cv.onpointerdown=e=>{drag=[e.clientX,e.clientY,az,el];cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(drag){az=drag[2]-(e.clientX-drag[0])*.008;el=Math.max(.02,Math.min(Math.PI/2,drag[3]+(e.clientY-drag[1])*.006));draw()}};cv.onpointerup=()=>drag=null;cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.6,Math.min(2,zoom*Math.exp(-e.deltaY*.001)));draw()};
let table='<table><tr><th>관절 번호</th><th>왼팔 (rad)</th><th>왼팔 (°)</th><th>기존 오른팔 (rad)</th><th>기존 오른팔 (°)</th></tr>';for(let i=0;i<7;i++){let l=D.pose.left_joints_rad[i],r=D.applied_right_joints[i];table+=`<tr><td>J${i+1}</td><td>${l.toFixed(5)}</td><td>${(l*180/Math.PI).toFixed(2)}</td><td>${r.toFixed(5)}</td><td>${(r*180/Math.PI).toFixed(2)}</td></tr>`}document.querySelector('#table').innerHTML=table+'</table>';document.querySelector('#coordinates').innerHTML='<p><b>적용 EE 좌표 · base_link (m)</b><br>왼팔: '+D.record.ee_xyz_m[0].map(x=>x.toFixed(3)).join(', ')+'<br>오른팔: '+D.applied_right_xyz.map(x=>x.toFixed(3)).join(', ')+'</p>';
function tick(n){if(playing&&last){t=Math.min(total(),t+Math.min(.1,(n-last)/1000));if(t>=total())playing=false}last=n;draw();requestAnimationFrame(tick)}window.previewData=D;window.seekTo=value=>{t=Math.max(0,Math.min(total(),value));playing=false;draw()};resize();requestAnimationFrame(tick);
</script></html>'''
